  "Are passionate about authentic Italian food and hospitality.": { es:"Sienten pasión por la auténtica comida italiana y la hospitalidad.", it:"Sono appassionati di autentica cucina italiana e ospitalità.", pt:"São apaixonados por comida italiana autêntica e hospitalidade." },
  "Want to build a strong local presence in their community.": { es:"Quieren construir una fuerte presencia local en su comunidad.", it:"Vogliono costruire una forte presenza locale nella loro comunità.", pt:"Querem construir uma forte presença local em sua comunidade." },
  "Are prepared to follow brand, product and operating standards.": { es:"Están preparados para seguir los estándares de marca, producto y operación.", it:"Sono pronti a seguire gli standard di marca, prodotto e operatività.", pt:"Estão preparados para seguir os padrões de marca, produto e operação." },
  "Have management, hospitality, food-service or business experience — or are ready to build the right operating team.":
    { es:"Tienen experiencia en gestión, hospitalidad, food service o negocios — o están dispuestos a formar el equipo operativo adecuado.",
      it:"Hanno esperienza nella gestione, nell'ospitalità, nella ristorazione o negli affari — o sono pronti a costruire il giusto team operativo.",
      pt:"Têm experiência em gestão, hospitalidade, food service ou negócios — ou estão dispostos a montar a equipe operacional certa." },
  "Understand that quality and consistency are central to the Puccettoni identity.": { es:"Entienden que la calidad y la consistencia son centrales para la identidad de Puccettoni.", it:"Capiscono che qualità e coerenza sono centrali per l'identità di Puccettoni.", pt:"Entendem que qualidade e consistência são centrais para a identidade da Puccettoni." },
  "Support": { es:"Soporte", it:"Supporto", pt:"Suporte" },
  "Built around the experience": { es:"Construido en torno a la experiencia", it:"Costruito intorno all'esperienza", pt:"Construído em torno da experiência" },
  "Qualified franchise partners may receive guidance and support in areas such as:": { es:"Los socios franquiciados cualificados podrán recibir orientación y soporte en áreas como:", it:"I partner franchisee qualificati potranno ricevere orientamento e supporto in aree come:", pt:"Parceiros franqueados qualificados poderão receber orientação e suporte em áreas como:" },
  "Brand identity and guest-experience standards.": { es:"Identidad de marca y estándares de experiencia del cliente.", it:"Identità di marca e standard dell'esperienza per il cliente.", pt:"Identidade de marca e padrões de experiência do cliente." },
  "Menu structure and product preparation standards.": { es:"Estructura del menú y estándares de preparación de los productos.", it:"Struttura del menu e standard di preparazione dei prodotti.", pt:"Estrutura do menu e padrões de preparação dos produtos." },
  "Operational training.": { es:"Formación operativa.", it:"Formazione operativa.", pt:"Treinamento operacional." },
  "Ordering systems and technology.": { es:"Sistemas de pedidos y tecnología.", it:"Sistemi di ordinazione e tecnologia.", pt:"Sistemas de pedidos e tecnologia." },
  "Approved supplier and ingredient guidance.": { es:"Orientación sobre proveedores e ingredientes aprobados.", it:"Indicazioni su fornitori e ingredienti approvati.", pt:"Orientação sobre fornecedores e ingredientes aprovados." },
  "Launch preparation and local marketing materials.": { es:"Preparación del lanzamiento y materiales de marketing local.", it:"Preparazione del lancio e materiali di marketing locale.", pt:"Preparação para o lançamento e materiais de marketing local." },
  "Ongoing operational communication.": { es:"Comunicación operativa continua.", it:"Comunicazione operativa continua.", pt:"Comunicação operacional contínua." },
  "Next Step": { es:"Siguiente Paso", it:"Prossimo Passo", pt:"Próximo Passo" },
  "Start the Conversation": { es:"Comienza la Conversación", it:"Inizia la Conversazione", pt:"Comece a Conversa" },
  "If the Puccettoni concept speaks to your market and your vision, we invite you to begin the conversation and request additional information.":
    { es:"Si el concepto de Puccettoni encaja con tu mercado y tu visión, te invitamos a iniciar la conversación y solicitar más información.",
      it:"Se il concept di Puccettoni rispecchia il tuo mercato e la tua visione, ti invitiamo a iniziare la conversazione e a richiedere ulteriori informazioni.",
      pt:"Se o conceito da Puccettoni conversa com o seu mercado e a sua visão, convidamos você a iniciar a conversa e solicitar mais informações." },
  "Simple Inquiry Process": { es:"Proceso de Contacto Simple", it:"Processo di Contatto Semplice", pt:"Processo de Contato Simples" },
  "Introduce yourself": { es:"Preséntate", it:"Presentati", pt:"Apresente-se" },
  "Share your market interest": { es:"Comparte tu mercado de interés", it:"Indica il tuo mercato di interesse", pt:"Compartilhe seu mercado de interesse" },
  "Tell us about your background": { es:"Cuéntanos sobre tu experiencia", it:"Raccontaci la tua esperienza", pt:"Conte-nos sobre seu histórico" },
  "Receive follow-up information": { es:"Recibe información de seguimiento", it:"Ricevi informazioni di follow-up", pt:"Receba informações de acompanhamento" },
  "Full Name *": { es:"Nombre Completo *", it:"Nome Completo *", pt:"Nome Completo *" },
