  "Ready When You Are": { es:"Listos Cuando Tú Quieras", it:"Pronti Quando Vuoi", pt:"Prontos Quando Você Quiser" },
  "Ready to <em>order</em>?": { es:"¿Listo para <em>pedir</em>?", it:"Pronto a <em>ordinare</em>?", pt:"Pronto para <em>pedir</em>?" },
  "Choose your location and we’ll get cooking. Fresh from Pompano Beach or Fort Lauderdale, straight to you.":
    { es:"Elige tu sede y nos ponemos a cocinar. Fresco desde Pompano Beach o Fort Lauderdale, directo para ti.",
      it:"Scegli la sede e iniziamo a cucinare. Fresco da Pompano Beach o Fort Lauderdale, dritto da te.",
      pt:"Escolha sua unidade e começamos a cozinhar. Fresquinho de Pompano Beach ou Fort Lauderdale, direto para você." },

  /* ---------- Store pages (Pompano / Fort Lauderdale) ---------- */
  "Authentic Italian Pizza &amp; Food · Pompano Beach · <b>Order direct · pickup &amp; delivery</b>": { es:"Auténtica Pizza y Comida Italiana · Pompano Beach · <b>Pide directo · recogida y delivery</b>", it:"Autentica Pizza e Cucina Italiana · Pompano Beach · <b>Ordina diretto · ritiro e consegna</b>", pt:"Autêntica Pizza e Comida Italiana · Pompano Beach · <b>Peça direto · retirada e delivery</b>" },
  "Authentic Italian Pizza &amp; Food · Fort Lauderdale · <b>Order direct · pickup &amp; delivery</b>": { es:"Auténtica Pizza y Comida Italiana · Fort Lauderdale · <b>Pide directo · recogida y delivery</b>", it:"Autentica Pizza e Cucina Italiana · Fort Lauderdale · <b>Ordina diretto · ritiro e consegna</b>", pt:"Autêntica Pizza e Comida Italiana · Fort Lauderdale · <b>Peça direto · retirada e delivery</b>" },
  "Pompano Beach · Florida": { es:"Pompano Beach · Florida", it:"Pompano Beach · Florida", pt:"Pompano Beach · Flórida" },
  "Fort Lauderdale · Florida": { es:"Fort Lauderdale · Florida", it:"Fort Lauderdale · Florida", pt:"Fort Lauderdale · Flórida" },
  "Authentic Italian,<br><em>made fresh.</em>": { es:"Auténtico italiano,<br><em>hecho al momento.</em>", it:"Autentico italiano,<br><em>fatto al momento.</em>", pt:"Autêntico italiano,<br><em>feito na hora.</em>" },
  "Authentic artisan Italian pizza, gnocchi, panzerotti, focaccia sandwiches and pastries. Order direct, pick up or have it delivered.":
    { es:"Auténtica pizza italiana artesanal, gnocchi, panzerotti, sándwiches de focaccia y pastelería. Pide directo, recoge o recíbelo en tu casa.",
      it:"Autentica pizza italiana artigianale, gnocchi, panzerotti, panini di focaccia e pasticceria. Ordina diretto, ritira o fatti consegnare.",
      pt:"Autêntica pizza italiana artesanal, gnocchi, panzerotti, sanduíches de focaccia e doces. Peça direto, retire ou receba em casa." },
  "<span class=\"star\">★★★★★</span> 4.8 on delivery · loved across Broward County": { es:"<span class=\"star\">★★★★★</span> 4.8 en delivery · querido en todo Broward County", it:"<span class=\"star\">★★★★★</span> 4.8 sulle consegne · amato in tutta la Broward County", pt:"<span class=\"star\">★★★★★</span> 4.8 no delivery · amado em todo o Broward County" },
  "Featured": { es:"Destacados", it:"In Evidenza", pt:"Destaques" },
  "Puccettoni <em>Favorites</em>": { es:"<em>Favoritos</em> de Puccettoni", it:"<em>Preferiti</em> di Puccettoni", pt:"<em>Favoritos</em> da Puccettoni" },
  "Explore our most-loved categories and order directly through Toast.": { es:"Explora nuestras categorías más queridas y pide directamente a través de Toast.", it:"Esplora le nostre categorie più amate e ordina direttamente tramite Toast.", pt:"Explore nossas categorias mais queridas e peça diretamente pelo Toast." },
  "Order on Toast →": { es:"Pedir en Toast →", it:"Ordina su Toast →", pt:"Pedir no Toast →" },
  "Our Story": { es:"Nuestra Historia", it:"La Nostra Storia", pt:"Nossa História" },
  "Not American pizza.<br><em>Italian, for real.</em>": { es:"No es pizza americana.<br><em>Italiana, de verdad.</em>", it:"Non è pizza americana.<br><em>Italiana, davvero.</em>", pt:"Não é pizza americana.<br><em>Italiana, de verdade.</em>" },
  "Puccettoni was born from a simple conviction: South Florida deserved Italian food made the genuine way — handcrafted dough, imported ingredients, and recipes that carry the old country in them.":
    { es:"Puccettoni nació de una convicción simple: el sur de Florida merecía comida italiana hecha de la manera auténtica — masa artesanal, ingredientes importados y recetas que llevan dentro al viejo país.",
      it:"Puccettoni è nata da una convinzione semplice: il sud della Florida meritava cucina italiana fatta nel modo autentico — impasto artigianale, ingredienti importati e ricette che portano in sé il vecchio paese.",
      pt:"A Puccettoni nasceu de uma convicção simples: o sul da Flórida merecia comida italiana feita do jeito genuíno — massa artesanal, ingredientes importados e receitas que carregam o velho continente." },
  "Every pizza, focaccia and panzerotto is made in-house by Chef Marco, who treats his craft the way Italians always have: as a matter of family pride.":
    { es:"Cada pizza, focaccia y panzerotto se hace en casa por el Chef Marco, que cuida su oficio como los italianos siempre lo han hecho: como una cuestión de orgullo familiar.",
      it:"Ogni pizza, focaccia e panzerotto è preparato in casa dallo Chef Marco, che cura la sua arte come gli italiani hanno sempre fatto: come una questione di orgoglio familiare.",
      pt:"Cada pizza, focaccia e panzerotto é feito na casa pelo Chef Marco, que trata seu ofício como os italianos sempre fizeram: como uma questão de orgulho de família." },
  "A Slice, A Future": { es:"Una Porción, Un Futuro", it:"Una Fetta, Un Futuro", pt:"Uma Fatia, Um Futuro" },
  "Good food with a <em>local heart</em>": { es:"Buena comida con <em>corazón local</em>", it:"Buon cibo con <em>cuore locale</em>", pt:"Boa comida com <em>coração local</em>" },
  "Puccettoni believes good food can also do good. Part of every order helps support children in our community through local partners.":
    { es:"Puccettoni cree que la buena comida también puede hacer el bien. Parte de cada pedido ayuda a apoyar a los niños de nuestra comunidad a través de socios locales.",
      it:"Puccettoni crede che il buon cibo possa anche fare del bene. Parte di ogni ordine aiuta a sostenere i bambini della nostra comunità tramite partner locali.",
      pt:"A Puccettoni acredita que comida boa também pode fazer o bem. Parte de cada pedido ajuda a apoiar crianças da nossa comunidade por meio de parceiros locais." },
  "You order": { es:"Tú pides", it:"Tu ordini", pt:"Você pede" },
  "What people say": { es:"Lo que dice la gente", it:"Cosa dice la gente", pt:"O que as pessoas dizem" },
  "Word travels <em>fast</em>": { es:"La voz corre <em>rápido</em>", it:"La voce corre <em>veloce</em>", pt:"A notícia corre <em>rápido</em>" },
  "\"Excellent pizza and true Italian flavors — Marco works hard to make it happen.\"": { es:"\"Pizza excelente y auténticos sabores italianos — Marco se esfuerza para lograrlo.\"", it:"\"Pizza eccellente e veri sapori italiani — Marco lavora sodo per renderlo possibile.\"", pt:"\"Pizza excelente e sabores italianos de verdade — o Marco se dedica para isso acontecer.\"" },
  "Local diner": { es:"Comensal local", it:"Cliente locale", pt:"Cliente local" },
  "\"The best focaccia sandwiches — better than anything I had in Italy.\"": { es:"\"Los mejores sándwiches de focaccia — mejores que cualquiera que probé en Italia.\"", it:"\"I migliori panini di focaccia — meglio di qualsiasi cosa abbia mangiato in Italia.\"", pt:"\"Os melhores sanduíches de focaccia — melhores do que qualquer um que comi na Itália.\"" },
  "DoorDash regular": { es:"Cliente habitual de DoorDash", it:"Cliente abituale di DoorDash", pt:"Cliente frequente do DoorDash" },
  "\"So excited to have such a great place right in my neighborhood.\"": { es:"\"Qué emoción tener un lugar tan bueno justo en mi barrio.\"", it:"\"Felicissimo di avere un posto così bello proprio nel mio quartiere.\"", pt:"\"Muito feliz de ter um lugar tão bom bem no meu bairro.\"" },
