  /* ---------- Lead landing (teste) ---------- */
  "Authentic Italian, made fresh in Fort Lauderdale · <b>Now delivering</b>": { es:"Auténtico italiano, hecho al momento en Fort Lauderdale · <b>Ahora con delivery</b>", it:"Autentico italiano, fatto al momento a Fort Lauderdale · <b>Ora con consegna</b>", pt:"Autêntico italiano, feito na hora em Fort Lauderdale · <b>Agora com delivery</b>" },
  "A taste of the old country": { es:"Un sabor del viejo país", it:"Un sapore del vecchio paese", pt:"Um sabor do velho continente" },
  "Your first bite,<br><em>on us.</em>": { es:"Tu primer bocado,<br><em>va por nuestra cuenta.</em>", it:"Il tuo primo morso,<br><em>offre la casa.</em>", pt:"Sua primeira mordida,<br><em>é por nossa conta.</em>" },
  "Hand-crafted dough, imported ingredients, family recipes. Join our table and get a little welcome gift with your first order.":
    { es:"Masa artesanal, ingredientes importados, recetas de familia. Únete a nuestra mesa y recibe un pequeño regalo de bienvenida con tu primer pedido.",
      it:"Impasto artigianale, ingredienti importati, ricette di famiglia. Unisciti alla nostra tavola e ricevi un piccolo regalo di benvenuto con il tuo primo ordine.",
      pt:"Massa artesanal, ingredientes importados, receitas de família. Junte-se à nossa mesa e ganhe um presente de boas-vindas no seu primeiro pedido." },
  "Welcome Offer": { es:"Oferta de Bienvenida", it:"Offerta di Benvenuto", pt:"Oferta de Boas-Vindas" },
  "A free <em>focaccia</em><br>with your first order": { es:"Una <em>focaccia</em> gratis<br>con tu primer pedido", it:"Una <em>focaccia</em> gratis<br>con il tuo primo ordine", pt:"Uma <em>focaccia</em> grátis<br>no seu primeiro pedido" },
  "Sign up below and we'll send your welcome gift straight to your phone. One taste of the focaccia people say beats Italy's.":
    { es:"Regístrate abajo y enviaremos tu regalo de bienvenida directo a tu teléfono. Un bocado de la focaccia que, según dicen, supera a la de Italia.",
      it:"Iscriviti qui sotto e invieremo il tuo regalo di benvenuto direttamente sul telefono. Un assaggio della focaccia che, dicono, batte quella italiana.",
      pt:"Cadastre-se abaixo e enviaremos seu presente de boas-vindas direto para o seu telefone. Uma mordida na focaccia que, dizem, supera a da Itália." },
  "WhatsApp / Phone": { es:"WhatsApp / Teléfono", it:"WhatsApp / Telefono", pt:"WhatsApp / Telefone" },
  "What sounds best tonight?": { es:"¿Qué te apetece esta noche?", it:"Cosa ti va stasera?", pt:"O que cai bem hoje à noite?" },
  "Focaccia sandwiches": { es:"Sándwiches de focaccia", it:"Panini di focaccia", pt:"Sanduíches de focaccia" },
  "Pasta": { es:"Pasta", it:"Pasta", pt:"Massa" },
  "Catering / events": { es:"Catering / eventos", it:"Catering / eventi", pt:"Catering / eventos" },
  "Claim My Welcome Gift": { es:"Quiero Mi Regalo de Bienvenida", it:"Richiedi il Mio Regalo di Benvenuto", pt:"Quero Meu Presente de Boas-Vindas" },
  "No spam — just the welcome gift and the occasional good offer. Unsubscribe anytime.": { es:"Sin spam — solo el regalo de bienvenida y alguna buena oferta de vez en cuando. Cancela cuando quieras.", it:"Niente spam — solo il regalo di benvenuto e qualche buona offerta ogni tanto. Disiscriviti quando vuoi.", pt:"Sem spam — só o presente de boas-vindas e uma boa oferta de vez em quando. Cancele quando quiser." },
  "Your welcome gift is on its way. Check your phone — and come hungry.": { es:"Tu regalo de bienvenida está en camino. Revisa tu teléfono — y ven con hambre.", it:"Il tuo regalo di benvenuto sta arrivando. Controlla il telefono — e vieni affamato.", pt:"Seu presente de boas-vindas está a caminho. Confira seu telefone — e venha com fome." },
  "<span class=\"star\">★★★★★</span> <b>4.8</b> on delivery": { es:"<span class=\"star\">★★★★★</span> <b>4.8</b> en delivery", it:"<span class=\"star\">★★★★★</span> <b>4.8</b> sulle consegne", pt:"<span class=\"star\">★★★★★</span> <b>4.8</b> no delivery" },
  "🔥 Wood-fired tradition": { es:"🔥 Tradición al horno de leña", it:"🔥 Tradizione del forno a legna", pt:"🔥 Tradição do forno a lenha" },
  "🇮🇹 Imported ingredients": { es:"🇮🇹 Ingredientes importados", it:"🇮🇹 Ingredienti importati", pt:"🇮🇹 Ingredientes importados" },
  "Truly Italian": { es:"Verdaderamente Italiano", it:"Davvero Italiano", pt:"Verdadeiramente Italiano" },
  "Not American pizza. Real recipes, real ingredients, made by Chef Marco the way it's done in Italy.":
    { es:"No es pizza americana. Recetas de verdad, ingredientes de verdad, hechos por el Chef Marco como se hace en Italia.",
      it:"Non è pizza americana. Ricette vere, ingredienti veri, preparati dallo Chef Marco come si fa in Italia.",
      pt:"Não é pizza americana. Receitas de verdade, ingredientes de verdade, feitos pelo Chef Marco do jeito que se faz na Itália." },
  "Fresh, fast, local": { es:"Fresco, rápido, local", it:"Fresco, veloce, locale", pt:"Fresco, rápido, local" },
  "Made to order and delivered hot across Fort Lauderdale and the neighborhood.": { es:"Hecho al momento y entregado caliente en Fort Lauderdale y el vecindario.", it:"Fatto al momento e consegnato caldo a Fort Lauderdale e in zona.", pt:"Feito na hora e entregue quentinho em Fort Lauderdale e na vizinhança." },
  "Loved already": { es:"Ya querido", it:"Già amato", pt:"Já é amado" },
  "4.8 stars on delivery and reviews that mention the chef by name. Come see why.": { es:"4.8 estrellas en delivery y reseñas que mencionan al chef por su nombre. Ven a ver por qué.", it:"4.8 stelle sulle consegne e recensioni che citano lo chef per nome. Vieni a scoprire perché.", pt:"4.8 estrelas no delivery e avaliações que citam o chef pelo nome. Venha ver por quê." },
  "Hungry <em>now?</em>": { es:"¿Con hambre <em>ahora?</em>", it:"Fame <em>adesso?</em>", pt:"Com fome <em>agora?</em>" },
  "Order direct or through your favorite app — your welcome gift works either way.": { es:"Pide directo o a través de tu app favorita — tu regalo de bienvenida funciona igual.", it:"Ordina diretto o tramite la tua app preferita — il tuo regalo di benvenuto vale in entrambi i casi.", pt:"Peça direto ou pelo seu app favorito — seu presente de boas-vindas vale dos dois jeitos." },
  "Claim &amp; Order": { es:"Reclamar y Pedir", it:"Richiedi e Ordina", pt:"Resgatar e Pedir" },

  /* ---------- Common attribute values (placeholders, aria-labels) ---------- */
  "Open menu": { es:"Abrir menú", it:"Apri menu", pt:"Abrir menu" },
  "Close menu": { es:"Cerrar menú", it:"Chiudi menu", pt:"Fechar menu" },
